arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -d "token=<TOKEN>&channel=CQXA0DU15US&limit=100" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for m in d.get('messages',[]):
    print('---', m.get('ts'), m.get('user'))
    print(m.get('text'))
    if m.get('reactions'):
        for r in m['reactions']:
            print('  reaction:', r.get('name'), r.get('users'))
"

